package com.bank.collections;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class CollectionsOverviewTest {

    // ═══ LIST: ordered, indexed, duplicates OK ═══
    @Test
    void list_orderedWithDuplicates() {
        List<String> txnLog = new ArrayList<>();
        txnLog.add("DEBIT-1000");
        txnLog.add("CREDIT-5000");
        txnLog.add("DEBIT-1000");  // duplicate OK!

        assertThat(txnLog).hasSize(3);
        assertThat(txnLog.get(0)).isEqualTo("DEBIT-1000");  // indexed access O(1)
        assertThat(txnLog).containsExactly("DEBIT-1000", "CREDIT-5000", "DEBIT-1000");
    }

    // ═══ SET: no duplicates ═══
    @Test
    void set_uniqueAccountNumbers() {
        Set<String> accountIds = new HashSet<>();
        accountIds.add("SAV2001");
        accountIds.add("CUR3001");
        accountIds.add("SAV2001");  // duplicate REJECTED!

        assertThat(accountIds).hasSize(2);  // only 2, not 3!
        assertThat(accountIds).contains("SAV2001", "CUR3001");
    }

    // ═══ MAP: key→value lookup ═══
    @Test
    void map_accountBalanceLookup() {
        Map<String, BigDecimal> balances = new HashMap<>();
        balances.put("SAV2001", new BigDecimal("75000"));
        balances.put("CUR3001", new BigDecimal("120000"));

        assertThat(balances.get("SAV2001")).isEqualByComparingTo("75000");  // O(1) lookup!
        assertThat(balances.containsKey("SAV2001")).isTrue();
        assertThat(balances).hasSize(2);
    }

    // ═══ QUEUE: FIFO processing ═══
    @Test
    void queue_transactionProcessing() {
        Queue<String> pending = new LinkedList<>();
        pending.offer("TXN-001");
        pending.offer("TXN-002");
        pending.offer("TXN-003");

        assertThat(pending.poll()).isEqualTo("TXN-001");  // FIFO: first in, first out!
        assertThat(pending.poll()).isEqualTo("TXN-002");
        assertThat(pending).hasSize(1);
    }

    // ═══ ALGORITHMS ═══
    @Test
    void algorithms_sortSearchShuffle() {
        List<String> accounts = new ArrayList<>(List.of("CUR3001", "SAV2001", "FD4001"));

        Collections.sort(accounts);  // natural order
        assertThat(accounts).containsExactly("CUR3001", "FD4001", "SAV2001");

        int idx = Collections.binarySearch(accounts, "FD4001");  // must be sorted!
        assertThat(idx).isEqualTo(1);

        assertThat(Collections.frequency(List.of("A", "B", "A", "A"), "A")).isEqualTo(3);
    }

    // ═══ IMMUTABLE (Java 9+) ═══
    @Test
    void immutable_cannotModify() {
        List<String> fixed = List.of("SAV2001", "CUR3001");
        assertThatThrownBy(() -> fixed.add("FD4001"))
            .isInstanceOf(UnsupportedOperationException.class);
        // Immutable! Cannot add/remove/set.
    }

    // ═══ PRIORITY QUEUE: highest priority first ═══
    @Test
    void priorityQueue_smallestFirst() {
        Queue<Integer> pq = new PriorityQueue<>();
        pq.offer(50000);
        pq.offer(10000);
        pq.offer(75000);

        assertThat(pq.poll()).isEqualTo(10000);  // smallest first (min-heap)!
        assertThat(pq.poll()).isEqualTo(50000);
        assertThat(pq.poll()).isEqualTo(75000);
    }
}
